// Placing an order requires a signed-in customer
// Generated by the QA spec generator (rung 2) — deterministic assembly; do not hand-edit.

import { test, expect, credentialsFor } from '../../../fixtures';

test('TC-099: Placing an order requires a signed-in customer', async ({ api }) => {
  // reset_state is automatic (harness beforeEach)
  // reset_state step: satisfied by the automatic per-test reset
  const products: { id: number; name: string; description: string; price: number; stock: number; is_active: boolean }[] = await (await api.get('/api/products')).json();
  const inStock = products.filter((p) => p.stock >= 1).slice(0, 2);
  expect(inStock.length).toBe(2);
  const res = await api.post('/api/orders', { data: { items: inStock.map((p) => ({ product_id: p.id, quantity: 1 })) }, headers: { cookie: '' } });
  expect([401, 403]).toContain(res.status());
  // Expected (full): Unauthenticated order request rejected (401/403); no order created
  await api.post('/api/auth/login', { data: credentialsFor('locked_out_user') });
  // Expected: locked_out_user cannot sign in and cannot place an order
});
